targets.query:
from(bucket: "telegraf")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "snmp" and
    r._field == "fgSysCpuUsage" and
    r.sysName == "FortigateA-Sccc.sccc.edu"         // e.g., Fortigate1-Sccc
  )
  |> map(fn: (r) => ({
      r with _value:
        if float(v: r._value) <= 1.0 then float(v: r._value) * 100.0 else float(v: r._value)
  }))
  |> aggregateWindow(every: v.windowPeriod, fn: mean, createEmpty: false)
  |> yield(name: "cpu_percent")

from(bucket: "telegraf")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "snmp" and
    r._field == "fgSysMemUsage" and
    r.sysName == "FortigateA-Sccc.sccc.edu"
  )
  |> map(fn: (r) => ({
      r with _value:
        if float(v: r._value) <= 1.0 then float(v: r._value) * 100.0 else float(v: r._value)
  }))
  |> aggregateWindow(every: v.windowPeriod, fn: mean, createEmpty: false)
  |> yield(name: "mem_percent")

building =
from(bucket: "inventory")
  |> range(start: -1d)
  |> filter(fn: (r) =>
      r._measurement == "device_inventory" and
      r._field == "building"
  )
  |> group(columns: ["source"])
  |> last()
  |> map(fn: (r) => ({
      source: r.source,
      building: string(v: r._value),
      hasSnmp: false
  }))

snmp =
from(bucket: "telegraf")
  |> range(start: -2h)
  |> filter(fn: (r) =>
      r._measurement == "snmp" and
      r._field == "sysUpTime"
  )
  |> group(columns: ["source"])
  |> last()
  |> keep(columns: ["source"])
  |> map(fn: (r) => ({
      source: r.source,
      building: "",
      hasSnmp: true
  }))

union(tables: [building, snmp])
  |> group(columns: ["source"])
  |> reduce(
      identity: {
        building: "",
        hasSnmp: false
      },
      fn: (r, accumulator) => ({
        building:
          if accumulator.building != "" then accumulator.building else r.building,
        hasSnmp: accumulator.hasSnmp or r.hasSnmp
      })
  )
  |> filter(fn: (r) => r.hasSnmp == false)
  |> map(fn: (r) => ({
      Building: r.building,
      Source: r.source
  }))
  |> group(columns: [])
  |> sort(columns: ["Building"])
